  });

  const r2 = issueInvoice(r.value, []);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2026-10-07');
  assert.equal(r2.value.lines.length, 1);
});

test('issueInvoice assigns sequential numbers within same year', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, ['INV-2026-0001', 'INV-2026-0002']);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0003');
});

test('issueInvoice resets counter for new year', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, ['INV-2026-9999']);

  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2027-0001');
});

test('issueInvoice refuses to issue non-draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const issuedInvoice = { ...r.value, status: 'issued', number: 'INV-2026-0001' };

  const r2 = issueInvoice(issuedInvoice, []);

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'NOT_DRAFT');
});

test('issueInvoice handles counter overflow', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const existing = Array.from({ length: 9999 }, (_, i) => `INV-2026-${String(i + 1).padStart(4, '0')}`);

  const r2 = issueInvoice(r.value, existing);

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'COUNTER_OVERFLOW');
});

test('issueInvoice does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r.value));
  issueInvoice(r.value, []);

  assert.deepEqual(r.value, invoiceCopy);
});

test('issueInvoice preserves all invoice fields', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-09-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 2 },
    ],
  });

  const r2 = issueInvoice(r.value, ['INV-2026-0001']);

  assert.equal(r2.value.customerId, 'C-003');
  assert.equal(r2.value.issueDate, '2026-09-15');
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[0].name, 'Logo package');
  assert.equal(r2.value.lines[1].sku, 'BRAND-BOOK');
  assert.equal(r2.value.lines[1].name, 'Brand guidelines document');
});

