import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);

  assert.deepEqual(r.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 2,
    unitPrice: 8500,
    vatRate: 21,
  });

  assert.deepEqual(r.value.lines[1], {
    sku: 'HOST-MONTH',
    name: 'Website hosting (month)',
    qty: 1,
    unitPrice: 1500,
    vatRate: 21,
  });
});

test('createInvoice reports unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date formats', () => {
  const testCases = [
    '2026/10/07',
    '10-07-2026',
    '2026-10-7',
    '2026-1-07',
    '2026-10',
    '2026',
    'not a date',
    '2026-13-01',
    '2026-00-01',
    '2026-02-30',
    '2026-02-29',
    null,
    undefined,
  ];

  for (const dateStr of testCases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(r.ok, false, `Should reject: ${dateStr}`);
    assert.equal(r.error, 'DATE_INVALID', `Should be DATE_INVALID for: ${dateStr}`);
  }
});

test('createInvoice accepts valid leap year dates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.issueDate, '2024-02-29');
});

test('createInvoice rejects lines array that is empty', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects lines that is null or undefined', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  }), { ok: false, error: 'NO_LINES' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice validates qty is a positive integer', () => {
  const invalidQtys = [0, -1, 1.5, 'abc', null, undefined];

  for (const qty of invalidQtys) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(r.ok, false, `Should reject qty: ${qty}`);
    assert.equal(r.error, 'QTY_INVALID', `Should be QTY_INVALID for qty: ${qty}`);
  }
});

test('createInvoice reports unknown SKU', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));

  createInvoice(input);

  assert.deepEqual(input, inputCopy);
});

test('createInvoice returns copies of catalogue data', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  r.value.lines[0].name = 'Modified';
  r.value.lines[0].unitPrice = 999;
  r.value.lines[0].vatRate = 0;

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(r2.value.lines[0].name, 'Design work (hour)');
  assert.equal(r2.value.lines[0].unitPrice, 8500);
  assert.equal(r2.value.lines[0].vatRate, 21);
});

test('createInvoice validates first invalid line and stops', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'NOPE', qty: 1 },
    ],
  });
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_SKU');
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 3,
    unitPrice: 8500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 25500);
});

test('lineTotal handles single unit', () => {
  const line = {
    sku: 'HOST-MONTH',
    name: 'Website hosting (month)',
    qty: 1,
    unitPrice: 1500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 1500);
});

test('lineTotal handles large quantities', () => {
  const line = {
    sku: 'STICKER',
    name: 'Sticker sheet',
    qty: 1000,
    unitPrice: 50,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 17000);
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 2 * 8500 + 3 * 9500 + 1 * 1500);
  assert.equal(totals.subtotal, 47000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 47000);
});

test('invoiceTotals handles different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 8500 + 100 * 37 + 60000);
  assert.equal(totals.subtotal, 72200);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 72200);
});

test('invoiceTotals does not mutate invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r.value));
  invoiceTotals(r.value);

  assert.deepEqual(r.value, invoiceCopy);
});

test('addLine adds a new line to a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const r2 = addLine(r.value, { sku: 'HOST-MONTH', qty: 1 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.deepEqual(r2.value.lines[1], {
    sku: 'HOST-MONTH',
    name: 'Website hosting (month)',
    qty: 1,
    unitPrice: 1500,
    vatRate: 21,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 5);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
});

test('addLine validates qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const testCases = [0, -1, 1.5, null, undefined];

  for (const qty of testCases) {
    const r2 = addLine(r.value, { sku: 'HOST-MONTH', qty });
    assert.equal(r2.ok, false, `Should reject qty: ${qty}`);
    assert.equal(r2.error, 'QTY_INVALID');
  }
});

test('addLine reports unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = addLine(r.value, { sku: 'UNKNOWN-SKU', qty: 1 });

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'UNKNOWN_SKU');
});

test('addLine refuses to modify non-draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const nonDraftInvoice = { ...r.value, status: 'sent' };

  const r2 = addLine(nonDraftInvoice, { sku: 'HOST-MONTH', qty: 1 });

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'NOT_DRAFT');
});

test('addLine does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r.value));
  addLine(r.value, { sku: 'HOST-MONTH', qty: 1 });

  assert.deepEqual(r.value, invoiceCopy);
});

test('removeLine removes a line from a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'HOST-MONTH', qty: 1 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  const r2 = removeLine(r.value, 'HOST-MONTH');

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
});

test('removeLine reports line not found', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = removeLine(r.value, 'NOPE');

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'LINE_NOT_FOUND');
});

test('removeLine refuses to remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = removeLine(r.value, 'DES-HOUR');

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'NO_LINES');
});

test('removeLine refuses to modify non-draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const nonDraftInvoice = { ...r.value, status: 'sent' };

  const r2 = removeLine(nonDraftInvoice, 'DES-HOUR');

  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const invoiceCopy = JSON.parse(JSON.stringify(r.value));
  removeLine(r.value, 'DES-HOUR');

  assert.deepEqual(r.value, invoiceCopy);
});

test('lineDiscount returns 0 for no discount', () => {
  const line = {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 2,
