    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'NOPE', qty: 1 },
    ],
  });
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_SKU');
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 3,
    unitPrice: 8500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 25500);
});

test('lineTotal handles single unit', () => {
  const line = {
    sku: 'HOST-MONTH',
    name: 'Website hosting (month)',
    qty: 1,
    unitPrice: 1500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 1500);
});

test('lineTotal handles large quantities', () => {
  const line = {
    sku: 'STICKER',
    name: 'Sticker sheet',
    qty: 1000,
    unitPrice: 50,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 17000);
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 2 * 8500 + 3 * 9500 + 1 * 1500);
  assert.equal(totals.subtotal, 47000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 47000);
});

test('invoiceTotals handles different VAT rates', () => {
  const r = createInvoice({
